  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","word","converge","zoom","accent","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  word: "remocn",
  converge: 128,
  zoom: 5,
  accent: "#3B5BFD",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type TitleConvergeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TitleConvergeBase>;

const TitleConvergeInner = forwardRef<
  HTMLDivElement,
  TitleConvergeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TitleConverge>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TitleConvergeBase
          {...(componentProps as unknown as ComponentProps<typeof TitleConvergeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TitleConverge = Interactive.withSchema({
  Component: TitleConvergeInner,
  componentName: "<TitleConverge>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
